Lemma SG_frame st st1 BL :
  s_groups st1 = s_groups st -> s_slots st1 = s_slots st ->
  (forall m, (exists b, hosts st b m) -> geom (MR st1 m) = geom (MR st m)) ->
  (forall s m i, s_slots st !! s = Some (m, i) -> exists b, hosts st b m) ->
