Definition apF (st : mstate) (kr : N * region) : Z := if is_metakind_b (snd kr) then frontier st (fst kr) (snd kr) / PGSZ - 1 else 0.
Lemma apages_msum st : apages st = msum (apF st) (s_regions st).
Proof.
