Lemma QM_take X st m d : s_metas st !! m = None -> QM X st d ->
  QM (xidle X (m :: x_idle X)) (take_st st m) d /\ ncarved (take_st st m) = ncarved st + 1
  /\ s_regions (take_st st m) = s_regions st /\ apages (take_st st m) = apages st
